**The Problem:**
```python
cache = {}

def fibonacci(n):
    if n < 2:
        return n
    if n not in cache:
        cache[n] = fibonacci(n-1) + fibonacci(n-2)
    return cache[n]

print(fibonacci(100))  # Still slow!
```

This is slow because the cache only helps for exact matches. We're still calling fibonacci(99) and fibonacci(98) which aren't cached until after they return.

**The Fix: Use memoization decorator**:
```python
from functools import lru_cache

@lru_cache(maxsize=None)
def fibonacci(n):
    if n < 2:
        return n
    return fibonacci(n-1) + fibonacci(n-2)

print(fibonacci(100))  # Instant
```

Or manual caching:
```python
cache = {}

def fibonacci(n):
    if n in cache:
        return cache[n]
    if n < 2:
        result = n
    else:
        result = fibonacci(n-1) + fibonacci(n-2)
    cache[n] = result
    return result
```

**Why manual approach was slow**: We only cache after computing both recursive calls. Better to check cache at the START of function.

**The Problem:**
```python
class Car:
    def __init__(self, brand, model, price):
        self.brand = brand
        self.model = model
        self.price = price

    def is_expensive(self):
        return self.price > 50000

    def discount(self, percent):
        self.price = self.price * (1 - percent / 100)

# Issues:
# 1. No validation
# 2. Modifying price directly breaks data
# 3. No immutability where needed
```

**The Fix: Use properties and validation**:
```python
class Car:
    def __init__(self, brand, model, price):
        self.brand = brand
        self.model = model
        self._original_price = self._validate_price(price)
        self._current_price = self._original_price

    @staticmethod
    def _validate_price(price):
        if not isinstance(price, (int, float)) or price < 0:
            raise ValueError("Price must be non-negative number")
        return price

    @property
    def price(self):
        return self._current_price

    @price.setter
    def price(self, value):
        self._current_price = self._validate_price(value)

    def is_expensive(self):
        return self.price > 50000

    def get_discount(self, percent):
        return self.price * (1 - percent / 100)

    def apply_discount(self, percent):
        self.price = self.get_discount(percent)

# Usage:
car = Car("Toyota", "Camry", 25000)
print(car.get_discount(10))  # 22500 (doesn't modify)
car.apply_discount(10)  # Actually modifies
car.price = -100  # ValueError: Price must be non-negative
```

**Key improvements**:
- Validation in __init__
- Properties for controlled access
- Separate methods for read (get_discount) and write (apply_discount)

***args**: Variable-length positional arguments. Becomes tuple.

****kwargs**: Variable-length keyword arguments. Becomes dict.

```python
def print_args(*args):
    for arg in args:
        print(arg)

print_args(1, 2, 3, 'hello')
# Args: (1, 2, 3, 'hello')

def print_kwargs(**kwargs):
    for key, value in kwargs.items():
        print(f"{key}: {value}")

print_kwargs(name='Alice', age=30, city='NYC')
# Kwargs: {'name': 'Alice', 'age': 30, 'city': 'NYC'}
```

**Use case 1: Flexible functions**:
```python
def log(level, message, *args, **kwargs):
    timestamp = kwargs.get('timestamp', True)
    extra = kwargs.get('extra', '')

    output = f"[{level}] {message}"
    if args:
        output += f" {args}"
    if extra:
        output += f" - {extra}"
    print(output)

log('INFO', 'User logged in', 'alice', extra='from mobile')
```

**Use case 2: Wrapper functions**:
```python
def timeit_decorator(func):
    def wrapper(*args, **kwargs):
        start = time.time()
        result = func(*args, **kwargs)  # Pass through
        elapsed = time.time() - start
        print(f"Took {elapsed:.2f}s")
        return result
    return wrapper

@timeit_decorator
def slow_function(a, b, c=10):
    return a + b + c

slow_function(1, 2)  # Works
slow_function(1, 2, c=20)  # Also works
```

**Use case 3: Factory pattern**:
```python
class Factory:
    @staticmethod
    def create(class_name, *args, **kwargs):
        cls = globals()[class_name]
        return cls(*args, **kwargs)

obj = Factory.create('MyClass', 1, 2, name='test')
```

**Order of parameters**:
```python
# Positional -> default -> *args -> keyword-only -> **kwargs
def func(a, b=2, *args, c=3, d=4, **kwargs):
    pass

func(1)  # a=1, b=2
func(1, 2, 3, 4, c=5, d=6, e=7)  # e=7 goes to kwargs
```

**Unpacking with * and **:
```python
args = (1, 2, 3)
func(*args)  # Unpacks to func(1, 2, 3)

kwargs = {'name': 'Alice', 'age': 30}
func(**kwargs)  # Unpacks to func(name='Alice', age=30)

# Combine
func(0, *args, **kwargs)  # func(0, 1, 2, 3, name='Alice', age=30)
```

**Key Takeaway**: Use *args for flexible positional arguments, **kwargs for flexible keyword arguments. Both allow writing more generic, reusable code.

**Decorator**: Function that wraps another function/class to modify its behavior.

```python
def my_decorator(func):
    def wrapper():
        print("Before")
        func()
        print("After")
    return wrapper

@my_decorator
def greet():
    print("Hello")

greet()
# Output:
# Before
# Hello
# After
```

**How decorators work**:
```python
# This:
@decorator
def func():
    pass

# Is equivalent to:
def func():
    pass
func = decorator(func)
```

**Decorator with arguments**:
```python
def repeat(times):
    def decorator(func):
        def wrapper():
            for _ in range(times):
                func()
        return wrapper
    return decorator

@repeat(times=3)
def greet():
    print("Hello")

greet()
# Output:
# Hello
# Hello
# Hello
```

**Preserving function metadata**:
```python
import functools

def my_decorator(func):
    @functools.wraps(func)  # Preserves __name__, __doc__
    def wrapper(*args, **kwargs):
        print(f"Calling {func.__name__}")
        return func(*args, **kwargs)
    return wrapper

@my_decorator
def add(a, b):
    """Add two numbers"""
    return a + b

print(add.__name__)  # 'add' (not 'wrapper')
print(add.__doc__)   # 'Add two numbers'
```

**Practical example: Timing decorator**:
```python
import time
import functools

def timeit(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        start = time.time()
        result = func(*args, **kwargs)
        elapsed = time.time() - start
        print(f"{func.__name__} took {elapsed:.4f}s")
        return result
    return wrapper

@timeit
def slow_function():
    time.sleep(2)

slow_function()  # Prints: slow_function took 2.0043s
```

**Practical example: Memoization**:
```python
import functools

def memoize(func):
    cache = {}

    @functools.wraps(func)
    def wrapper(*args):
        if args not in cache:
            cache[args] = func(*args)
        return cache[args]
    return wrapper

@memoize
def fibonacci(n):
    if n < 2:
        return n
    return fibonacci(n-1) + fibonacci(n-2)

print(fibonacci(100))  # Instant (uses cache)
```

**Using functools.lru_cache (built-in)**:
```python
from functools import lru_cache

@lru_cache(maxsize=128)
def fibonacci(n):
    if n < 2:
        return n
    return fibonacci(n-1) + fibonacci(n-2)

print(fibonacci(100))  # Instant
```

**Decorator for class methods**:
```python
def validate_positive(func):
    @functools.wraps(func)
    def wrapper(self, value):
        if value < 0:
            raise ValueError("Must be positive")
        return func(self, value)
    return wrapper

class BankAccount:
    @validate_positive
    def deposit(self, amount):
        self.balance += amount

    @validate_positive
    def withdraw(self, amount):
        self.balance -= amount
```

**Key Takeaway**: Decorators wrap functions to add behavior. Use @functools.wraps to preserve metadata. Apply decorators for cross-cutting concerns like logging, caching, validation.

**Type hints**: Annotations that specify expected types. Python doesn't enforce them (unlike static languages).

```python
# Function arguments and return type
def greet(name: str) -> str:
    return f"Hello, {name}"

print(greet("Alice"))  # "Hello, Alice"
print(greet(123))      # Still works! Type hint not enforced

# Variable type hints
age: int = 30
count: int  # Just annotation, no value
name: str = "Bob"
```

**Common type hints**:
```python
from typing import List, Dict, Tuple, Optional, Union, Set

# Collections
def process_list(items: List[int]) -> int:
    return sum(items)

def create_mapping(keys: List[str], values: List[int]) -> Dict[str, int]:
    return dict(zip(keys, values))

# Tuple (fixed size)
def get_coordinates() -> Tuple[float, float]:
    return (1.0, 2.0)

# Optional (value or None)
def find_user(user_id: int) -> Optional[str]:
    return "Alice" if user_id == 1 else None

# Union (multiple types)
def process_input(value: Union[int, str]) -> str:
    return str(value)

# Set
def get_unique_items(items: List[int]) -> Set[int]:
    return set(items)
```

**Generic types** (Python 3.9+):
```python
# Don't need to import List, Dict, etc.
def process_list(items: list[int]) -> int:
    return sum(items)

def create_mapping(keys: list[str], values: list[int]) -> dict[str, int]:
    return dict(zip(keys, values))
```

**Custom classes**:
```python
class Person:
    def __init__(self, name: str, age: int) -> None:
        self.name = name
        self.age = age

def create_person(data: Dict[str, Union[str, int]]) -> Person:
    return Person(data['name'], data['age'])
```

**Type checkers** (don't affect runtime):
```python
# Use mypy, pyright, or pydantic to check types
# mypy program.py
# mypy will catch type errors at compile-time

def add(a: int, b: int) -> int:
    return a + b

result = add("5", "10")  # mypy error: Argument 1 to "add" has incompatible type
```

**Callable type**:
```python
from typing import Callable

def execute(callback: Callable[[int, int], int], x: int, y: int) -> int:
    return callback(x, y)

def multiply(a: int, b: int) -> int:
    return a * b

result = execute(multiply, 3, 4)  # 12
```

**Default values**:
```python
def greet(name: str, greeting: str = "Hello") -> str:
    return f"{greeting}, {name}"
```

**Key point**: Type hints are hints for tools and humans, not enforced by Python. Use them for better code documentation and IDE support.

**break**: Exits the loop immediately.
```python
for i in range(10):
    if i == 5:
        break
    print(i)
# Output: 0 1 2 3 4

while True:
    user_input = input("Enter 'quit' to exit: ")
    if user_input == 'quit':
        break
    print(f"You said: {user_input}")
```

**continue**: Skips current iteration, moves to next.
```python
for i in range(5):
    if i == 2:
        continue
    print(i)
# Output: 0 1 3 4

# Skip even numbers
for num in range(10):
    if num % 2 == 0:
        continue
    print(num)  # Prints odd numbers
```

**pass**: Does nothing. Placeholder.
```python
# Empty function definition
def not_implemented():
    pass

# Empty class
class Placeholder:
    pass

# Empty except block (catch and ignore)
try:
    risky_operation()
except ValueError:
    pass  # Ignore ValueError

# Empty if block
if condition:
    pass  # Will implement later
else:
    do_something()
```

**Comparison**:
```python
for i in range(5):
    if i == 2:
        break        # Exits entire loop
    if i == 1:
        continue     # Skips to next iteration
    pass             # Does nothing
    print(i)

# Output: 0
# (i==1 continues, i==2 breaks)
```

**With else clause**:
```python
# else after loop executes if loop completes normally
for i in range(5):
    if i == 10:
        break
else:
    print("Loop completed")  # Printed

for i in range(5):
    if i == 2:
        break
else:
    print("Loop completed")  # NOT printed (exited early)
```

**Use cases**:
```python
# break: search for item
for item in items:
    if item == target:
        print("Found!")
        break
else:
    print("Not found!")

# continue: skip invalid items
for item in items:
    if not is_valid(item):
        continue
    process(item)

# pass: stubbing out code
def feature_not_ready():
    pass

class FutureClass:
    pass
```

**Key difference**:
- `break`: Stop everything
- `continue`: Stop current iteration, do next
- `pass`: Literally do nothing (placeholder)

**else clause on loop**: Executes if loop completes normally (no break).

```python
for i in range(5):
    print(i)
else:
    print("Loop completed!")  # Executed

# Output:
# 0 1 2 3 4
# Loop completed!
```

**With break**:
```python
for item in [1, 2, 3, 4, 5]:
    if item == 3:
        break
else:
    print("Found nothing")  # NOT executed (break exits)
```

**While with else**:
```python
i = 0
while i < 5:
    if i == 10:
        break
    i += 1
else:
    print("Completed normally")  # Executed
```

**Use case: Search**:
```python
def find_item(items, target):
    for item in items:
        if item == target:
            return f"Found {target}!"
    else:
        return "Not found"

print(find_item([1, 2, 3], 2))  # Found 2!
print(find_item([1, 2, 3], 5))  # Not found
```

**@property**: Converts method to attribute-like access.
```python
class Circle:
    def __init__(self, radius):
        self._radius = radius

    @property
    def area(self):
        return 3.14159 * self._radius ** 2

c = Circle(5)
print(c.area)  # 78.53975 - accessed like attribute
```

**@lru_cache**: Memoizes function results.
```python
from functools import lru_cache

@lru_cache(maxsize=128)
def fibonacci(n):
    if n < 2:
        return n
    return fibonacci(n-1) + fibonacci(n-2)

fib = fibonacci(100)  # Instant (cached)
```

**Combining them**:
```python
class DataProcessor:
    @property
    @lru_cache(maxsize=1)
    def expensive_data(self):
        # Computed once, cached
        return sum(range(1000000))

# Actually: can't combine directly like this
# Use manual caching instead
```

**Generator**: Produces values with yield.

**Coroutine**: Consumes values, uses yield to receive data.

```python
# Generator (producer)
def producer():
    for i in range(5):
        yield i

# Coroutine (consumer)
def consumer():
    while True:
        value = yield  # Wait for input
        print(f"Consumed: {value}")

# Use generator
for item in producer():
    print(item)  # 0 1 2 3 4

# Use coroutine
c = consumer()
next(c)  # Prime it
c.send(1)  # Sends 1 to consumer
c.send(2)  # Sends 2 to consumer
```

**Pipeline pattern**:
```python
def producer(target):
    for i in range(5):
        target.send(i)  # Send to next

def filter_even(target):
    while True:
        value = yield
        if value % 2 == 0:
            target.send(value)

def consumer():
    while True:
        value = yield
        print(f"Final: {value}")

c = consumer()
f = filter_even(c)
producer(f)  # Pipeline: produce -> filter -> consume
```

**Implement `__iter__()` and `__next__()`**:

```python
class CountUp:
    def __init__(self, max):
        self.max = max
        self.current = 0

    def __iter__(self):
        self.current = 0
        return self

    def __next__(self):
        if self.current < self.max:
            self.current += 1
            return self.current
        raise StopIteration

for num in CountUp(3):
    print(num)  # 1 2 3
```

**Using generator function** (simpler):
```python
class CountUp:
    def __init__(self, max):
        self.max = max

    def __iter__(self):
        for i in range(self.max):
            yield i + 1

for num in CountUp(3):
    print(num)  # 1 2 3
```

**Naive recursion** (slow: O(2^n)):
```python
def fibonacci(n):
    if n < 2:
        return n
    return fibonacci(n-1) + fibonacci(n-2)

fib(10)  # Slow, recalculates same values
```

**With memoization** (fast: O(n)):
```python
from functools import lru_cache

@lru_cache(maxsize=None)
def fibonacci(n):
    if n < 2:
        return n
    return fibonacci(n-1) + fibonacci(n-2)

fib(100)  # Instant!
```

**Iterative** (O(n), no recursion overhead):
```python
def fibonacci(n):
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a
```

**Generator** (memory efficient):
```python
def fibonacci():
    a, b = 0, 1
    while True:
        yield a
        a, b = b, a + b

fib_gen = fibonacci()
for _ in range(10):
    print(next(fib_gen))

**super()**: Call parent class method (with MRO).

```python
class Animal:
    def speak(self):
        print("Some sound")

class Dog(Animal):
    def speak(self):
        super().speak()  # Call parent
        print("Woof!")

dog = Dog()
dog.speak()
# Output:
# Some sound
# Woof!
```

**Without super() (hardcoding)**:
```python
class Dog(Animal):
    def speak(self):
        Animal.speak(self)  # Brittle - hardcoded class name
        print("Woof!")
```

**Multiple inheritance**:
```python
class A:
    def method(self):
        return "A"

class B(A):
    def method(self):
        return "B -> " + super().method()

class C(A):
    def method(self):
        return "C -> " + super().method()

class D(B, C):
    pass

print(D().method())
# B -> C -> A
# super() follows MRO, not hardcoded names
```

**functools.lru_cache**: Memoization.

```python
from functools import lru_cache

@lru_cache(maxsize=128)
def fibonacci(n):
    if n < 2:
        return n
    return fibonacci(n-1) + fibonacci(n-2)
```

**functools.wraps**: Preserve function metadata.

```python
from functools import wraps

def timeit_decorator(func):
    @wraps(func)  # Preserves __name__, __doc__
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper
```

**functools.partial**: Create new function with fixed arguments.

```python
from functools import partial

def multiply(a, b):
    return a * b

multiply_by_2 = partial(multiply, 2)
print(multiply_by_2(5))  # 10
```
